def solution(bandage, health, attacks):
    time, recovery, bonus = bandage
    max_health = health
    current_health = health

    attack_index = 0
    consecutive_time = 0

    while current_health > 0 and attack_index < len(attacks):
        if consecutive_time >= time:
            current_health += recovery * time + bonus
            if current_health > max_health:
                current_health = max_health
            consecutive_time = 0

        if attack_index < len(attacks) and attacks[attack_index][0] == consecutive_time + 1:
            damage = attacks[attack_index][1]
            current_health -= damage
            if current_health <= 0:
                return -1
            attack_index += 1
        else:
            consecutive_time += 1

    return current_health if current_health > 0 else -1

