def solution(edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    node_count = len(graph)
    doughnut_count = 0
    stick_count = 0
    octagon_count = 0

    visited = set()

    def dfs(node):
        nonlocal doughnut_count, stick_count, octagon_count
        if node in visited:
            return

        visited.add(node)

        children = graph[node]

        if len(children) == 0:
            doughnut_count += 1
        elif len(children) == 1:
            stick_count += 1
        else:
            octagon_count += 1

        for child in children:
            dfs(child)

    for node in range(node_count):
        if node not in visited:
            dfs(node)

    return [node_count + 1] + [doughnut_count, stick_count, octagon_count] if octagon_count > 0 else [node_count + 1] + [doughnut_count, stick_count] if stick_count > 0 else [node_count + 1] + [doughnut_count] if doughnut_count > 0 else [node_count + 1]

